create table if not exists private.gst_transaction_requests_v520(tenant_id uuid not null,request_id text not null,operation text not null,request_hash text not null,status text not null default 'processing' check(status in('processing','completed')),source_type text null,source_id uuid null,snapshot_id uuid null,journal_id uuid null,response jsonb null,created_by uuid null,created_at timestamptz not null default now(),completed_at timestamptz null,primary key(tenant_id,request_id),check(length(request_hash)=64),check((status='processing') or (source_type is not null and source_id is not null and snapshot_id is not null and journal_id is not null and response is not null and completed_at is not null)));
create unique index if not exists ux_gst_transaction_request_source_v520 on private.gst_transaction_requests_v520(tenant_id,source_type,source_id) where source_id is not null;
revoke all on private.gst_transaction_requests_v520 from public,anon,authenticated;
grant select,insert,update,delete on private.gst_transaction_requests_v520 to service_role;
create or replace function private.gst_request_hash_v520(p_payload jsonb) returns text language sql immutable security definer set search_path=public,private,pg_temp as $$ select encode(extensions.digest(convert_to(coalesce(p_payload,'{}'::jsonb)::text,'UTF8'),'sha256'),'hex'); $$;
create or replace function private.gst_request_begin_v520(p_tenant_id uuid,p_request_id text,p_operation text,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_request text:=nullif(trim(coalesce(p_request_id,'')),'');v_operation text:=nullif(trim(coalesce(p_operation,'')),'');v_hash text:=private.gst_request_hash_v520(p_payload);r private.gst_transaction_requests_v520%rowtype;begin if v_request is null then raise exception 'Request ID is required';end if;if length(v_request)>200 then raise exception 'Request ID is too long';end if;if v_operation is null then raise exception 'GST operation is required';end if;if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':gst520:'||v_request,0));select * into r from private.gst_transaction_requests_v520 where tenant_id=p_tenant_id and request_id=v_request for update;if found then if r.operation<>v_operation then raise exception 'Request ID already belongs to another GST operation';end if;if r.request_hash<>v_hash then raise exception 'Request ID was already used with a different request payload';end if;if r.status='completed' then return jsonb_build_object('existing',true,'status','completed','request_hash',r.request_hash,'source_type',r.source_type,'source_id',r.source_id,'snapshot_id',r.snapshot_id,'journal_id',r.journal_id,'response',r.response);end if;raise exception 'GST request is in an incomplete processing state and requires recovery review';end if;insert into private.gst_transaction_requests_v520(tenant_id,request_id,operation,request_hash,status,created_by) values(p_tenant_id,v_request,v_operation,v_hash,'processing',auth.uid());return jsonb_build_object('existing',false,'status','processing','request_hash',v_hash);end $$;
create or replace function private.gst_request_complete_v520(p_tenant_id uuid,p_request_id text,p_operation text,p_source_type text,p_source_id uuid,p_snapshot_id uuid,p_journal_id uuid,p_response jsonb) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare r private.gst_transaction_requests_v520%rowtype;begin select * into r from private.gst_transaction_requests_v520 where tenant_id=p_tenant_id and request_id=trim(p_request_id) for update;if not found then raise exception 'GST request state not found';end if;if r.operation<>p_operation then raise exception 'GST request operation mismatch';end if;if r.status='completed' then if r.source_type=p_source_type and r.source_id=p_source_id and r.snapshot_id=p_snapshot_id and r.journal_id=p_journal_id then return r.response;end if;raise exception 'Completed GST request evidence does not match retry result';end if;if p_source_type is null or p_source_id is null or p_snapshot_id is null or p_journal_id is null then raise exception 'GST request cannot complete without source/snapshot/journal evidence';end if;if coalesce(p_response,'{}'::jsonb)='{}'::jsonb then raise exception 'GST request response is required';end if;update private.gst_transaction_requests_v520 set status='completed',source_type=p_source_type,source_id=p_source_id,snapshot_id=p_snapshot_id,journal_id=p_journal_id,response=p_response,completed_at=now() where tenant_id=p_tenant_id and request_id=trim(p_request_id);return p_response;end $$;
revoke all on function private.gst_request_hash_v520(jsonb) from public,anon,authenticated;
revoke all on function private.gst_request_begin_v520(uuid,text,text,jsonb) from public,anon,authenticated;
revoke all on function private.gst_request_complete_v520(uuid,text,text,text,uuid,uuid,uuid,jsonb) from public,anon,authenticated;
grant execute on function private.gst_request_hash_v520(jsonb) to service_role;
grant execute on function private.gst_request_begin_v520(uuid,text,text,jsonb) to service_role;
grant execute on function private.gst_request_complete_v520(uuid,text,text,text,uuid,uuid,uuid,jsonb) to service_role;
insert into public.thq_schema_releases(migration_no,schema_version,release_name,notes) values(240,'5.2.0-foundation','GST Atomic Request Contract','Adds private SHA-256 request-payload idempotency for v5.2 atomic GST transactions. Same request+same payload returns the same evidence; same request with changed payload/operation is rejected. Completed requests are bound to source, immutable snapshot and journal IDs.') on conflict(migration_no) do update set schema_version=excluded.schema_version,release_name=excluded.release_name,notes=excluded.notes;